import sys
from collections import deque

x, y = map(int, sys.stdin.read().split())
m = max(abs(x), abs(y)) + 4
dist = {(0, 0): 0}
dq = deque([(0, 0)])
while dq:
    a, b = dq.popleft()
    if (a, b) == (x, y):
        break
    for da, db in ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)):
        na, nb = a + da, b + db
        if abs(na) <= m and abs(nb) <= m and (na, nb) not in dist:
            dist[(na, nb)] = dist[(a, b)] + 1
            dq.append((na, nb))
print(dist[(x, y)])

